or.message.includes('Unsupported state or unable to authenticate data')) {\r\n          throw new Error('Decryption failed: Authentication tag verification failed - data may be corrupted or tampered');\r\n        }\r\n        throw new Error(`Failed to download and decrypt blob: ${error.message}`);\r\n      }\r\n      throw new Error('Failed to download and decrypt blob: Unknown error');\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Convert encryption metadata to blob metadata format (all values must be strings)\r\n   */\r\n  private serializeMetadata(metadata: EncryptionMetadata): Record\u003cstring, string\u003e {\r\n    return {\r\n      encryption_wrappedkey: metadata.wrappedKey,\r\n      encryption_keyid: metadata.keyId,\r\n      encryption_iv: metadata.iv,\r\n      encryption_authtag: metadata.authTag,\r\n      encryption_algorithm: metadata.algorithm,\r\n    };\r\n  }\r\n\r\n  /**\r\n   * Parse blob metadata back to encryption metadata format\r\n   */\r\n  private deserializeMetadata(blobMetadata: Record\u003cstring, string\u003e): EncryptionMetadata {\r\n    return {\r\n      wrappedKey: blobMetadata.encryption_wrappedkey || '',\r\n      keyId: blobMetadata.encryption_keyid || '',\r\n      iv: blobMetadata.encryption_iv || '',\r\n      authTag: blobMetadata.encryption_authtag || '',\r\n      algorithm: blobMetadata.encryption_algorithm || 'aes-256-gcm',\r\n    };\r\n  }\r\n\r\n  /**\r\n   * Convert a readable stream to a buffer\r\n   */\r\n  private async streamToBuffer(readableStream: NodeJS.ReadableStream): Promise\u003cBuffer\u003e {\r\n    return new Promise((resolve, reject) =\u003e {\r\n      const chunks: Buffer[] = [];\r\n      readableStream.on('data', (chunk) =\u003e {\r\n        chunks.push(Buffer.from(chunk));\r\n      });\r\n      readableStream.on('end', () =\u003e {\r\n        resolve(Buffer.concat(chunks));\r\n      });\r\n      readableStream.on('error', reject);\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Delete a blob from storage\r\n   */\r\n  async deleteBlob(blobName: string): Promise\u003cvoid\u003e {\r\n    try {\r\n      const containerClient = this.blobServiceClient.getContainerClient(this.containerName);\r\n      const blobClient = containerClient.getBlockBlobClient(blobName);\r\n      await blobClient.deleteIfExists();\r\n    } catch (error) {\r\n      if (error instanceof Error) {\r\n        throw new Error(`Failed to delete blob: ${error.message}`);\r\n      }\r\n      throw new Error('Failed to delete blob: Unknown error');\r\n    }\r\n  }\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { DefaultAzureCredential } from '@azure/identity';\r\nimport { BlobServiceClient } from '@azure/storage-blob';\r\nimport { KeyClient } from '@azure/keyvault-keys';\r\n\r\nexport interface AzureConfig {\r\n  credential: DefaultAzureCredential;\r\n  blobServiceClient: BlobServiceClient;\r\n  keyClient: KeyClient;\r\n  keyName: string;\r\n}\r\n\r\n/**\r\n * Configuration module that builds necessary Azure connections\r\n * for both Blob Storage and Key Vault using managed identity authentication.\r\n */\r\nexport class ConfigurationManager {\r\n  private static instance: AzureConfig | null = null;\r\n\r\n  /**\r\n   * Get or create a singleton configuration instance\r\n   */\r\n  static getConfig(): AzureConfig {\r\n    if (!ConfigurationManager.instance) {\r\n      ConfigurationManager.instance = ConfigurationManager.createConfig();\r\n    }\r\n    return ConfigurationManager.instance;\r\n  }\r\n\r\n  /**\r\n   * Create Azure service clients with shared credential\r\n   */\r\n  private static createConfig(): AzureConfig {\r\n    // Read configuration from environment variables\r\n    const storageAccountUrl = process.env.AZURE_STORAGE_ACCOUNT_URL;\r\n    const keyVaultUrl = process.env.AZURE_KEYVAULT_URL;\r\n    const keyName = process.env.AZURE_KEYVAULT_KEY_NAME;\r\n\r\n    if (!storageAccountUrl) {\r\n      throw new Error('AZURE_STORAGE_ACCOUNT_URL environment variable is required');\r\n    }\r\n\r\n    if (!keyVaultUrl) {\r\n      throw new Error('AZURE_KEYVAULT_URL environment variable is required');\r\n    }\r\n\r\n    if (!keyName) {\r\n      throw new Error('AZURE_KEYVAULT_KEY_NAME environment variable is required');\r\n    }\r\n\r\n    // Create a single credential instance shared across all services\r\n    const credential = new DefaultAzureCredential();\r\n\r\n    // Initialize Blob Service Client\r\n    const blobServiceClient = new BlobServiceClient(storageAccountUrl, credential);\r\n\r\n    // Initialize Key Vault Key Client\r\n    const keyClient = new KeyClient(keyVaultUrl, credential);\r\n\r\n    return {\r\n      credential,\r\n      blobServiceClient,\r\n      keyClient,\r\n      keyName,\r\n    };\r\n  }\r\n\r\n  /**\r\n   * Reset the singleton instance (useful for testing)\r\n   */\r\n  static reset(): void {\r\n    ConfigurationManager.instance = null;\r\n  }\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { ConfigurationManager } from './config';\r\nimport { KeyManagementService } from './keyManagement';\r\nimport { EncryptedBlobService } from './blobStorage';\r\n\r\n/**\r\n * Main demo script that demonstrates the full encrypt-upload-download-decrypt round-trip.\r\n */\r\nasync function main() {\r\n  try {\r\n    console.log('=== Azure Encrypted Blob Storage Demo ===\\n');\r\n\r\n    // Get configuration\r\n    console.log('Initializing Azure connections...');\r\n    const config = ConfigurationManager.getConfig();\r\n    console.log('✓ Connected to Azure services\\n');\r\n\r\n    // Initialize services\r\n    const keyManagementService = new KeyManagementService(\r\n      config.keyClient,\r\n      config.keyName\r\n    );\r\n\r\n    const encryptedBlobService = new EncryptedBlobService(\r\n      config.blobServiceClient,\r\n      keyManagementService,\r\n      'encrypted-container'\r\n    );\r\n\r\n    // Get and display the Key Vault key ID\r\n    const keyId = await keyManagementService.getKeyId();\r\n    console.log(`Using Key Vault Key: ${keyId}\\n`);\r\n\r\n    // Sample data to encrypt and upload\r\n    const originalData = 'Hello, Azure! This is a secret message that will be encrypted using envelope encryption with Azure Key Vault and stored in Blob Storage.';\r\n    const blobName = `test-blob-${Date.now()}.enc`;\r\n\r\n    console.log('Original data:');\r\n    console.log(`  \"${originalData}\"\\n`);\r\n\r\n    // === UPLOAD AND ENCRYPT ===\r\n    console.log('Step 1: Encrypting and uploading...');\r\n    console.log('  - Generating 256-bit AES data encryption key (DEK) locally');\r\n    console.log('  - Encrypting data with AES-256-GCM');\r\n    console.log('  - Wrapping DEK with Key Vault key');\r\n    console.log('  - Uploading ciphertext and metadata to Blob Storage');\r\n\r\n    await encryptedBlobService.uploadEncrypted(blobName, originalData);\r\n    console.log(`✓ Encrypted blob uploaded: ${blobName}\\n`);\r\n\r\n    // === DOWNLOAD AND DECRYPT ===\r\n    console.log('Step 2: Downloading and decrypting...');\r\n    console.log('  - Downloading encrypted blob and metadata');\r\n    console.log('  - Unwrapping DEK with Key Vault key');\r\n    console.log('  - Decrypting data locally with AES-256-GCM');\r\n\r\n    const decryptedData = await encryptedBlobService.downloadDecrypted(blobName);\r\n    const decryptedString = decryptedData.toString('utf-8');\r\n    console.log(`✓ Blob downloaded and decrypted\\n`);\r\n\r\n    // === VERIFICATION ===\r\n    console.log('=== Verification ===');\r\n    console.log(`Vault Key ID: ${keyId}`);\r\n    \r\n    // Get wrapped DEK from blob metadata to display (for demonstration)\r\n    const containerClient = config.blobServiceClient.getContainerClient('encrypted-container');\r\n    const blobClient = containerClient.getBlockBlobClient(blobName);\r\n    const properties = await blobClient.getProperties();\r\n    const wrappedDEK = properties.metadata?.encryption_wrappedkey || 'N/A';\r\n    console.log(`Wrapped DEK (base64): ${wrappedDEK.substring(0, 64)}...`);\r\n    \r\n    console.log(`\\nDecrypted output: \"${decryptedString}\"`);\r\n    \r\n    // Verify round-trip success\r\n    if (decryptedString === originalData) {\r\n      console.log('\\n✓ SUCCESS: Round-trip encryption/decryption verified!');\r\n      console.log('  Original and decrypted data match perfectly.');\r\n    } else {\r\n      console.log('\\n✗ ERROR: Data mismatch!');\r\n      console.log('  Original and decrypted data do not match.');\r\n    }\r\n\r\n    // Cleanup\r\n    console.log('\\nCleaning up...');\r\n    await encryptedBlobService.deleteBlob(blobName);\r\n    console.log(`✓ Test blob deleted: ${blobName}`);\r\n\r\n    console.log('\\n=== Demo Complete ===');\r\n  } catch (error) {\r\n    console.error('\\n✗ Error:', error instanceof Error ? error.message : 'Unknown error');\r\n    process.exit(1);\r\n  }\r\n}\r\n\r\n// Run the demo\r\nmain();\r\n\n```\n\n### src\\keyManagement.ts\n```\nimport { KeyClient, CryptographyClient } from '@azure/keyvault-keys';\r\nimport * as crypto from 'crypto';\r\n\r\nexport interface WrappedKey {\r\n  encryptedKey: string; // Base64 encoded wrapped key\r\n  keyId: string; // Key Vault key ID used for wrapping\r\n}\r\n\r\n/**\r\n * Key management class that implements envelope encryption using Azure Key Vault.\r\n * \r\n * Generates data encryption keys (DEK) locally, uses Key Vault to wrap/unwrap them.\r\n * The raw DEK is never persisted, and the vault's key material never leaves Key Vault.\r\n */\r\nexport class KeyManagementService {\r\n  private keyClient: KeyClient;\r\n  private keyName: string;\r\n\r\n  constructor(keyClient: KeyClient, keyName: string) {\r\n    this.keyClient = keyClient;\r\n    this.keyName = keyName;\r\n  }\r\n\r\n  /**\r\n   * Generate a new data encryption key (DEK) locally and wrap it using Key Vault.\r\n   * \r\n   * @returns Object containing the wrapped key and the plaintext key (for immediate use)\r\n   */\r\n  async generateAndWrapDataKey(): Promise\u003c{ wrappedKey: WrappedKey; plaintextKey: Buffer }\u003e {\r\n    try {\r\n      // Generate a 256-bit (32 bytes) AES key locally\r\n      const plaintextKey = crypto.randomBytes(32);\r\n\r\n      // Get the key from Key Vault to obtain the cryptography client\r\n      const key = await this.keyClient.getKey(this.keyName);\r\n      const cryptoClient = new CryptographyClient(key, this.keyClient.vaultUrl);\r\n\r\n      // Wrap the data encryption key using the Key Vault key\r\n      const wrapResult = await cryptoClient.wrapKey('RSA-OAEP', plaintextKey);\r\n\r\n      if (!wrapResult.result) {\r\n        throw new Error('Key wrapping failed: no result returned');\r\n      }\r\n\r\n      const wrappedKey: WrappedKey = {\r\n        encryptedKey: Buffer.from(wrapResult.result).toString('base64'),\r\n        keyId: key.id!,\r\n      };\r\n\r\n      return { wrappedKey, plaintextKey };\r\n    } catch (error) {\r\n      if (error instanceof Error) {\r\n        throw new Error(`Failed to generate and wrap data key: ${error.message}`);\r\n      }\r\n      throw new Error('Failed to generate and wrap data key: Unknown error');\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Unwrap a data encryption key using Key Vault.\r\n   * \r\n   * @param wrappedKey - The wrapped key information\r\n   * @returns The plaintext data encryption key\r\n   */\r\n  async unwrapDataKey(wrappedKey: WrappedKey): Promise\u003cBuffer\u003e {\r\n    try {\r\n      // Get the key from Key Vault\r\n      const key = await this.keyClient.getKey(this.keyName);\r\n\r\n      // Verify the key ID matches (security check)\r\n      if (key.id !== wrappedKey.keyId) {\r\n        throw new Error(\r\n          `Key ID mismatch: expected ${wrappedKey.keyId}, got ${key.id}`\r\n        );\r\n      }\r\n\r\n      const cryptoClient = new CryptographyClient(key, this.keyClient.vaultUrl);\r\n\r\n      // Unwrap the data encryption key\r\n      const encryptedKeyBuffer = Buffer.from(wrappedKey.encryptedKey, 'base64');\r\n      const unwrapResult = await cryptoClient.unwrapKey('RSA-OAEP', encryptedKeyBuffer);\r\n\r\n      if (!unwrapResult.result) {\r\n        throw new Error('Key unwrapping failed: no result returned');\r\n      }\r\n\r\n      return Buffer.from(unwrapResult.result);\r\n    } catch (error) {\r\n      if (error instanceof Error) {\r\n        // Check for common Key Vault errors\r\n        if (error.message.includes('disabled')) {\r\n          throw new Error('Key Vault key is disabled and cannot be used for decryption');\r\n        }\r\n        if (error.message.includes('not found')) {\r\n          throw new Error('Key Vault key not found');\r\n        }\r\n        throw new Error(`Failed to unwrap data key: ${error.message}`);\r\n      }\r\n      throw new Error('Failed to unwrap data key: Unknown error');\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Get the current Key Vault key ID\r\n   */\r\n  async getKeyId(): Promise\u003cstring\u003e {\r\n    try {\r\n      const key = await this.keyClient.getKey(this.keyName);\r\n      return key.id!;\r\n    } catch (error) {\r\n      if (error instanceof Error) {\r\n        throw new Error(`Failed to get key ID: ${error.message}`);\r\n      }\r\n      throw new Error('Failed to get key ID: Unknown error');\r\n    }\r\n  }\r\n}\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"moduleResolution\": \"node\",\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code revie